// Full encyclopedia entries: Australia, victoria. Built from the Vitis Mundi atlas plus researched rules and history; checked 14 November 2026.
(function(){
APXF["au-alpine-valleys"] = {"lede": "The Ovens, Kiewa, Buckland and Buffalo river valleys around Bright and Myrtleford, registered in 1999, with vineyards up to about 1,000 m among former tobacco and hop farms.", "facts": [["Category", "GI"], ["Recognized", "1999"], ["Vineyard area", "About 240 ha"], ["Main grapes", "Chardonnay, Pinot Gris, Tempranillo, Prosecco, Shiraz, Saperavi"]], "sections": [["The place", "<p>Producers such as Billy Button, Mayford and Gapsted experiment widely.</p><p>About 1,580 growing degree days; alluvial soils; cold winters.</p>"], ["The rules", "<p>Australia's GI system was created in 1993, when amendments to the Australian Wine and Brandy Corporation Act set up the Geographical Indications Committee, partly to meet the terms of the 1994 wine agreement with the European Community, under which Australia also began phasing out names such as Burgundy, Champagne and Port. The committee, now part of Wine Australia, determines boundaries on application from local growers, following criteria that include the area's history, name, geology, climate and the existence of a viticultural identity. A GI on a label requires at least 85% of the wine from that GI, and the same 85% applies to vintage and variety. There are no rules on grapes, yields or winemaking: an Australian GI defines a place, not a style. This is a region, which under the regulations must be a single tract of land with at least five independently owned vineyards of at least five hectares each and usually produce at least 500 tonnes of grapes a year, and must be measurably homogeneous in its grape-growing attributes.</p>"], ["History", "<p>Former tobacco country in the Ovens, Kiewa, Buckland and Buffalo valleys.</p>"], ["In the glass", "<p>Italian varieties, Pinot Gris, sparkling.</p>"], ["For the exam", "<p>Former tobacco valleys; registered 1999.</p>"]], "producers": ["Billy Button", "Mayford", "Gapsted"], "sources": [["Wine Australia: Register of protected GIs and other terms", "https://www.wineaustralia.com/labelling/register-of-protected-gis-and-other-terms"], ["Wine Australia: Geographical indications", "https://www.wineaustralia.com/labelling/geographical-indications"]], "checked": "2026-11-14"};
APXF["au-beechworth"] = {"lede": "A gold-rush town in the foothills of the Victorian Alps that became a cult wine region thanks to Rick Kinzbrunner, who planted Giaconda at Everton Upper in 1982.", "facts": [["Category", "GI"], ["Recognized", "2000"], ["Vineyard area", "About 126 ha"], ["Main grapes", "Chardonnay, Shiraz, Nebbiolo, Pinot Noir"]], "sections": [["The place", "<p>Giaconda's Chardonnay, fermented with wild yeast and aged in a granite cave cellar, is one of Australia's most sought-after whites, and Kinzbrunner's Nebbiolo and Shiraz are equally serious. Sorrenberg (1985), Castagna (biodynamic Syrah and Sangiovese), Savaterre and A. Rodda followed.</p><p>About 1,720 growing degree days. Altitudes from about 200 to 1,000 m, on granite and on sandy, quartz-rich soils over decomposed granite; cool nights.</p>"], ["The rules", "<p>Australia's GI system was created in 1993, when amendments to the Australian Wine and Brandy Corporation Act set up the Geographical Indications Committee, partly to meet the terms of the 1994 wine agreement with the European Community, under which Australia also began phasing out names such as Burgundy, Champagne and Port. The committee, now part of Wine Australia, determines boundaries on application from local growers, following criteria that include the area's history, name, geology, climate and the existence of a viticultural identity. A GI on a label requires at least 85% of the wine from that GI, and the same 85% applies to vintage and variety. There are no rules on grapes, yields or winemaking: an Australian GI defines a place, not a style. This is a region, which under the regulations must be a single tract of land with at least five independently owned vineyards of at least five hectares each and usually produce at least 500 tonnes of grapes a year, and must be measurably homogeneous in its grape-growing attributes.</p>"], ["History", "<p>A gold-rush town where Rick Kinzbrunner planted Giaconda in the early 1980s; its Chardonnay is among Australia's most sought-after wines.</p>"], ["In the glass", "<p>Chardonnay, Shiraz.</p>"], ["For the exam", "<p>Giaconda; granite.</p>"]], "producers": ["Giaconda", "Sorrenberg", "Castagna", "Savaterre", "A. Rodda", "Fighting Gully Road"], "sources": [["Wine Australia: Register of protected GIs and other terms", "https://www.wineaustralia.com/labelling/register-of-protected-gis-and-other-terms"], ["Wine Australia: Geographical indications", "https://www.wineaustralia.com/labelling/geographical-indications"]], "checked": "2026-11-14"};
APXF["au-bendigo"] = {"lede": "Gold-rush Bendigo had more than 100 vineyards by 1880 until phylloxera arrived in 1893 and the government ordered vineyards destroyed.", "facts": [["Category", "GI"], ["Recognized", "2001"], ["Vineyard area", "About 609 ha"], ["Main grapes", "Shiraz, Cabernet Sauvignon, Chardonnay"]], "sections": [["The place", "<p>Stuart Anderson revived it at Balgownie in 1969, and the region now makes rich, minty Shiraz and Cabernet from small family producers.</p><p>Warm and dry (about 1,880 growing degree days, 496 mm of rain), on gravelly quartz soils over clay.</p>"], ["The rules", "<p>Australia's GI system was created in 1993, when amendments to the Australian Wine and Brandy Corporation Act set up the Geographical Indications Committee, partly to meet the terms of the 1994 wine agreement with the European Community, under which Australia also began phasing out names such as Burgundy, Champagne and Port. The committee, now part of Wine Australia, determines boundaries on application from local growers, following criteria that include the area's history, name, geology, climate and the existence of a viticultural identity. A GI on a label requires at least 85% of the wine from that GI, and the same 85% applies to vintage and variety. There are no rules on grapes, yields or winemaking: an Australian GI defines a place, not a style. This is a region, which under the regulations must be a single tract of land with at least five independently owned vineyards of at least five hectares each and usually produce at least 500 tonnes of grapes a year, and must be measurably homogeneous in its grape-growing attributes.</p>"], ["History", "<p>Gold-rush Bendigo had more than 100 vineyards by 1880; phylloxera arrived in 1893 and the government ordered vineyards destroyed. Stuart Anderson planted Balgownie in 1969, reviving the region.</p>"], ["In the glass", "<p>Rich Shiraz and Cabernet.</p>"], ["For the exam", "<p>Phylloxera 1893; Balgownie 1969.</p>"]], "producers": ["Balgownie Estate", "Sutton Grange", "Water Wheel", "Passing Clouds"], "sources": [["Wine Australia: Register of protected GIs and other terms", "https://www.wineaustralia.com/labelling/register-of-protected-gis-and-other-terms"], ["Wine Australia: Geographical indications", "https://www.wineaustralia.com/labelling/geographical-indications"]], "checked": "2026-11-14"};
APXF["au-central-victoria"] = {"lede": "The zone of central Victorian goldfields and river country, containing Bendigo, Heathcote, Goulburn Valley (with Nagambie Lakes), Strathbogie Ranges and Upper Goulburn.", "facts": [["Category", "GI"], ["Recognized", "1996"], ["Vineyard area", "About 4,363 ha"], ["Main grapes", "Shiraz, Cabernet Sauvignon, Marsanne, Chardonnay"]], "sections": [["The place", "<p>Its regions share a gold-rush history: most nineteenth-century vineyards here were planted with mining wealth and destroyed by phylloxera, and the modern industry began again in the 1960s and 1970s.</p>"], ["The rules", "<p>Australia's GI system was created in 1993, when amendments to the Australian Wine and Brandy Corporation Act set up the Geographical Indications Committee, partly to meet the terms of the 1994 wine agreement with the European Community, under which Australia also began phasing out names such as Burgundy, Champagne and Port. The committee, now part of Wine Australia, determines boundaries on application from local growers, following criteria that include the area's history, name, geology, climate and the existence of a viticultural identity. A GI on a label requires at least 85% of the wine from that GI, and the same 85% applies to vintage and variety. There are no rules on grapes, yields or winemaking: an Australian GI defines a place, not a style. This is a zone, a large administrative division within a state; zones were drawn to cover the wine states completely, and most regions sit inside one.</p>"], ["History", "<p>The Central Victoria zone covers the goldfields, where wine boomed with the gold rush of the 1850s.</p>"], ["In the glass", "<p>Shiraz, Marsanne, Cabernet.</p>"], ["For the exam", "<p>Zone: Bendigo, Heathcote, Goulburn Valley, Strathbogie Ranges, Upper Goulburn.</p>"]], "producers": ["Tahbilk", "Jasper Hill"], "sources": [["Wine Australia: Register of protected GIs and other terms", "https://www.wineaustralia.com/labelling/register-of-protected-gis-and-other-terms"], ["Wine Australia: Geographical indications", "https://www.wineaustralia.com/labelling/geographical-indications"]], "checked": "2026-11-14"};
APXF["au-geelong"] = {"lede": "Geelong was one of Australia's biggest wine districts in the 1860s and 1870s, planted by Swiss vignerons, and it was where phylloxera was found in 1877: the government ordered the vines uprooted, and the region vanished for 90 years.", "facts": [["Category", "GI"], ["Recognized", "1996"], ["Vineyard area", "About 466 ha"], ["Main grapes", "Pinot Noir, Chardonnay, Shiraz"]], "sections": [["The place", "<p>Revived from 1966 by Daryl and Nini Sefton at Idyll, it now makes some of Victoria's most distinctive Pinot, Chardonnay and Shiraz, from Gary Farr's By Farr and Bannockburn on the Moorabool Valley's limestone and basalt, and from the Bellarine Peninsula and Surf Coast.</p><p>Dry and windy (518 mm a year), with about 1,570 growing degree days. Three sub-areas: the Moorabool Valley (volcanic basalt and limestone), the Bellarine Peninsula (maritime) and the Surf Coast.</p>"], ["The rules", "<p>Australia's GI system was created in 1993, when amendments to the Australian Wine and Brandy Corporation Act set up the Geographical Indications Committee, partly to meet the terms of the 1994 wine agreement with the European Community, under which Australia also began phasing out names such as Burgundy, Champagne and Port. The committee, now part of Wine Australia, determines boundaries on application from local growers, following criteria that include the area's history, name, geology, climate and the existence of a viticultural identity. A GI on a label requires at least 85% of the wine from that GI, and the same 85% applies to vintage and variety. There are no rules on grapes, yields or winemaking: an Australian GI defines a place, not a style. This is a region, which under the regulations must be a single tract of land with at least five independently owned vineyards of at least five hectares each and usually produce at least 500 tonnes of grapes a year, and must be measurably homogeneous in its grape-growing attributes.</p>"], ["History", "<p>Swiss vignerons made Geelong one of Australia's biggest wine districts in the 1860s and 1870s. Phylloxera was found at Fyansford in 1877, the first in Victoria, and the government ordered vineyards uprooted. Daryl and Nini Sefton replanted at Idyll in 1966.</p>"], ["In the glass", "<p>Pinot Noir, Chardonnay, Shiraz.</p>"], ["For the exam", "<p>Phylloxera 1877; Swiss vignerons; Bannockburn (Gary Farr).</p>"]], "producers": ["By Farr", "Bannockburn Vineyards", "Clyde Park", "Lethbridge", "Scotchmans Hill", "Provenance", "Austin's"], "sources": [["Wine Australia: Register of protected GIs and other terms", "https://www.wineaustralia.com/labelling/register-of-protected-gis-and-other-terms"], ["Wine Australia: Geographical indications", "https://www.wineaustralia.com/labelling/geographical-indications"]], "checked": "2026-11-14"};
APXF["au-gippsland"] = {"lede": "A zone covering eastern Victoria from Phillip Island to the New South Wales border, with no registered regions and fewer than 200 ha of vines.", "facts": [["Category", "GI"], ["Recognized", "1996"], ["Vineyard area", "About 187 ha"], ["Main grapes", "Pinot Noir, Chardonnay"]], "sections": [["The place", "<p>It is famous for one estate: Bass Phillip, where Phillip Jones planted dense, unirrigated Pinot Noir at Leongatha South from 1979 and made wines that were compared with Burgundy grand crus. Burgundian Jean-Marie Fourrier became a partner in the estate in 2020.</p><p>South Gippsland is cool and wet, on deep, fertile red soils; East Gippsland is warmer.</p>"], ["The rules", "<p>Australia's GI system was created in 1993, when amendments to the Australian Wine and Brandy Corporation Act set up the Geographical Indications Committee, partly to meet the terms of the 1994 wine agreement with the European Community, under which Australia also began phasing out names such as Burgundy, Champagne and Port. The committee, now part of Wine Australia, determines boundaries on application from local growers, following criteria that include the area's history, name, geology, climate and the existence of a viticultural identity. A GI on a label requires at least 85% of the wine from that GI, and the same 85% applies to vintage and variety. There are no rules on grapes, yields or winemaking: an Australian GI defines a place, not a style. This is a zone, a large administrative division within a state; zones were drawn to cover the wine states completely, and most regions sit inside one.</p>"], ["History", "<p>The Gippsland zone covers eastern Victoria, a large area that has never registered a region. Bass Phillip, founded by Phillip Jones in 1979, made cult Pinot Noir here.</p>"], ["In the glass", "<p>Pinot Noir, Chardonnay.</p>"], ["For the exam", "<p>Zone without regions; Bass Phillip.</p>"]], "producers": ["Bass Phillip", "William Downie", "Lightfoot & Sons", "Narkoojee"], "sources": [["Wine Australia: Register of protected GIs and other terms", "https://www.wineaustralia.com/labelling/register-of-protected-gis-and-other-terms"], ["Wine Australia: Geographical indications", "https://www.wineaustralia.com/labelling/geographical-indications"]], "checked": "2026-11-14"};
APXF["au-glenrowan"] = {"lede": "Ned Kelly's last stand took place at Glenrowan in 1880, and Baileys of Glenrowan, founded in 1870, still makes thick, dry-grown Shiraz and fortified Muscat and Topaque on the red granite soils of the Warby Ranges.", "facts": [["Category", "GI"], ["Recognized", "2003"], ["Vineyard area", "About 205 ha"], ["Main grapes", "Shiraz, Durif, Muscat, Muscadelle, Cabernet Sauvignon"]], "sections": [["The place", "<p>Warm (about 2,020 growing degree days), on deep red loam derived from granite.</p>"], ["The rules", "<p>Australia's GI system was created in 1993, when amendments to the Australian Wine and Brandy Corporation Act set up the Geographical Indications Committee, partly to meet the terms of the 1994 wine agreement with the European Community, under which Australia also began phasing out names such as Burgundy, Champagne and Port. The committee, now part of Wine Australia, determines boundaries on application from local growers, following criteria that include the area's history, name, geology, climate and the existence of a viticultural identity. A GI on a label requires at least 85% of the wine from that GI, and the same 85% applies to vintage and variety. There are no rules on grapes, yields or winemaking: an Australian GI defines a place, not a style. This is a region, which under the regulations must be a single tract of land with at least five independently owned vineyards of at least five hectares each and usually produce at least 500 tonnes of grapes a year, and must be measurably homogeneous in its grape-growing attributes.</p>"], ["History", "<p>Ned Kelly's gang made its last stand at Glenrowan in 1880. Baileys of Glenrowan, founded in 1870, still makes dry-grown Shiraz and fortified Muscat.</p>"], ["In the glass", "<p>Big Shiraz; fortified Muscat.</p>"], ["For the exam", "<p>Ned Kelly 1880; Baileys 1870.</p>"]], "producers": ["Baileys of Glenrowan", "Taminick Cellars"], "sources": [["Wine Australia: Register of protected GIs and other terms", "https://www.wineaustralia.com/labelling/register-of-protected-gis-and-other-terms"], ["Wine Australia: Geographical indications", "https://www.wineaustralia.com/labelling/geographical-indications"]], "checked": "2026-11-14"};
APXF["au-goulburn-valley"] = {"lede": "The Goulburn River valley in north-central Victoria, from Seymour to Shepparton.", "facts": [["Category", "GI"], ["Recognized", "1999"], ["Vineyard area", "About 1,214 ha"], ["Main grapes", "Shiraz, Marsanne, Cabernet Sauvignon, Riesling"]], "sections": [["The place", "<p>Its heart is the Nagambie Lakes subregion, where Tahbilk has made wine since 1860; elsewhere irrigated orchards dominate. The broader region outside Nagambie Lakes is mostly irrigated orchard and dairy country, with vineyards that supply fruit for larger wineries.</p><p>Warm (about 2,100 growing degree days) and dry, on alluvial soils.</p>"], ["The rules", "<p>Australia's GI system was created in 1993, when amendments to the Australian Wine and Brandy Corporation Act set up the Geographical Indications Committee, partly to meet the terms of the 1994 wine agreement with the European Community, under which Australia also began phasing out names such as Burgundy, Champagne and Port. The committee, now part of Wine Australia, determines boundaries on application from local growers, following criteria that include the area's history, name, geology, climate and the existence of a viticultural identity. A GI on a label requires at least 85% of the wine from that GI, and the same 85% applies to vintage and variety. There are no rules on grapes, yields or winemaking: an Australian GI defines a place, not a style. This is a region, which under the regulations must be a single tract of land with at least five independently owned vineyards of at least five hectares each and usually produce at least 500 tonnes of grapes a year, and must be measurably homogeneous in its grape-growing attributes.</p>"], ["History", "<p>The Goulburn River valley holds Tahbilk, founded in 1860.</p>"], ["In the glass", "<p>Shiraz, Marsanne.</p>"], ["For the exam", "<p>Contains Nagambie Lakes.</p>"]], "producers": ["Tahbilk", "Mitchelton"], "sources": [["Wine Australia: Register of protected GIs and other terms", "https://www.wineaustralia.com/labelling/register-of-protected-gis-and-other-terms"], ["Wine Australia: Geographical indications", "https://www.wineaustralia.com/labelling/geographical-indications"]], "checked": "2026-11-14"};
APXF["au-grampians"] = {"lede": "The region around the sandstone Grampians ranges, Ararat and Great Western, whose cool, peppery, medium-bodied Shiraz is among Australia's most elegant.", "facts": [["Category", "GI"], ["Recognized", "1997"], ["Vineyard area", "About 640 ha"], ["Main grapes", "Shiraz, Riesling, Cabernet Sauvignon, Pinot Meunier"]], "sections": [["The place", "<p>Its history is gold-rush: Henry Best planted Concongella in 1866, and Hans Irvine's Great Western winery (later Seppelt) dug kilometres of tunnels ('drives') to age traditional-method sparkling wine from 1868 onward. Mount Langi Ghiran, Best's and The Story make the reference Shiraz today.</p><p>About 1,540 growing degree days; altitudes up to about 500 m on vineyards; soils of sandy loam over clay and granite-derived gravels.</p>"], ["The rules", "<p>Australia's GI system was created in 1993, when amendments to the Australian Wine and Brandy Corporation Act set up the Geographical Indications Committee, partly to meet the terms of the 1994 wine agreement with the European Community, under which Australia also began phasing out names such as Burgundy, Champagne and Port. The committee, now part of Wine Australia, determines boundaries on application from local growers, following criteria that include the area's history, name, geology, climate and the existence of a viticultural identity. A GI on a label requires at least 85% of the wine from that GI, and the same 85% applies to vintage and variety. There are no rules on grapes, yields or winemaking: an Australian GI defines a place, not a style. This is a region, which under the regulations must be a single tract of land with at least five independently owned vineyards of at least five hectares each and usually produce at least 500 tonnes of grapes a year, and must be measurably homogeneous in its grape-growing attributes.</p>"], ["History", "<p>Joseph Best and Henry Best started vineyards near Great Western in the 1860s; Best's Concongella nursery block holds rare old vines. Hans Irvine bought Joseph Best's winery in 1888 and built it into what became Seppelt Great Western, whose underground 'drives' were dug by former gold miners. Great Western sparkling Shiraz is a regional specialty.</p>"], ["In the glass", "<p>Peppery, medium-bodied Shiraz; sparkling Shiraz; Riesling.</p>"], ["For the exam", "<p>Best's; Seppelt Great Western drives; sparkling Shiraz.</p>"]], "producers": ["Best's", "Seppelt", "Mount Langi Ghiran", "The Story", "Grampians Estate"], "sources": [["Wine Australia: Register of protected GIs and other terms", "https://www.wineaustralia.com/labelling/register-of-protected-gis-and-other-terms"], ["Wine Australia: Geographical indications", "https://www.wineaustralia.com/labelling/geographical-indications"]], "checked": "2026-11-14"};
APXF["au-great-western"] = {"lede": "A subregion of the Grampians registered in 2007 around the village of Great Western.", "facts": [["Category", "GI"], ["Recognized", "2007"], ["Vineyard area", "About 468 ha"], ["Main grapes", "Shiraz, Pinot Meunier, Riesling, Chardonnay"]], "sections": [["The place", "<p>Its name had long been used on cheap sparkling wine made elsewhere by Seppelt, and its registration came with legally enforceable conditions on use. It contains Best's Concongella vineyard, planted from 1866, whose Nursery Block holds about 40 varieties, several of them unidentified, and some of the oldest Pinot Meunier and Dolcetto vines in the world.</p><p>Granite-derived sandy loams over clay, cool and dry.</p>"], ["The rules", "<p>Australia's GI system was created in 1993, when amendments to the Australian Wine and Brandy Corporation Act set up the Geographical Indications Committee, partly to meet the terms of the 1994 wine agreement with the European Community, under which Australia also began phasing out names such as Burgundy, Champagne and Port. The committee, now part of Wine Australia, determines boundaries on application from local growers, following criteria that include the area's history, name, geology, climate and the existence of a viticultural identity. A GI on a label requires at least 85% of the wine from that GI, and the same 85% applies to vintage and variety. There are no rules on grapes, yields or winemaking: an Australian GI defines a place, not a style. This is a subregion, which must meet the same tests as a region, at least five vineyards of five hectares and 500 tonnes, and be substantially discrete within its parent region.</p>"], ["History", "<p>Registered as a subregion in 2007, giving the historic village around Best's and Seppelt its own name within the Grampians.</p>"], ["In the glass", "<p>Shiraz, sparkling.</p>"], ["For the exam", "<p>Subregion 2007; Best's and Seppelt.</p>"]], "producers": ["Best's", "Seppelt"], "sources": [["Wine Australia: Register of protected GIs and other terms", "https://www.wineaustralia.com/labelling/register-of-protected-gis-and-other-terms"], ["Wine Australia: Geographical indications", "https://www.wineaustralia.com/labelling/geographical-indications"]], "checked": "2026-11-14"};
APXF["au-heathcote"] = {"lede": "Heathcote's fame rests on a band of deep red soil derived from Cambrian greenstone, volcanic rock about 500 million years old, that runs north-south along the Mount Camel Range for about 60 km.", "facts": [["Category", "GI"], ["Recognized", "2002"], ["Vineyard area", "About 1,695 ha"], ["Main grapes", "Shiraz, Cabernet Sauvignon, Tempranillo, Nebbiolo, Fiano"]], "sections": [["The place", "<p>On it Shiraz is dense yet fresh, with dark fruit, spice and fine tannin. Ron and Elva Laughton planted Jasper Hill in 1975 and their dry-grown, own-rooted Georgia's Paddock and Emily's Paddock Shiraz made the region famous; Wild Duck Creek, Paul Wilson and Tellurian followed. The GI was registered in 2002 after a dispute with Bendigo over the boundary.</p><p>About 1,880 growing degree days and only 521 mm of annual rain. Altitude 110 to 600 m. The Cambrian red soils hold water well, allowing dry-farming.</p>"], ["The rules", "<p>Australia's GI system was created in 1993, when amendments to the Australian Wine and Brandy Corporation Act set up the Geographical Indications Committee, partly to meet the terms of the 1994 wine agreement with the European Community, under which Australia also began phasing out names such as Burgundy, Champagne and Port. The committee, now part of Wine Australia, determines boundaries on application from local growers, following criteria that include the area's history, name, geology, climate and the existence of a viticultural identity. A GI on a label requires at least 85% of the wine from that GI, and the same 85% applies to vintage and variety. There are no rules on grapes, yields or winemaking: an Australian GI defines a place, not a style. This is a region, which under the regulations must be a single tract of land with at least five independently owned vineyards of at least five hectares each and usually produce at least 500 tonnes of grapes a year, and must be measurably homogeneous in its grape-growing attributes.</p>"], ["History", "<p>Heathcote's red Cambrian soil, from greenstone about 500 million years old, made its Shiraz famous after Ron Laughton planted Jasper Hill in 1975. The boundary, which runs north-south along the Mount Camel Range, was contested when the GI was registered in 2002.</p>"], ["In the glass", "<p>Deep, savoury Shiraz.</p>"], ["For the exam", "<p>Cambrian red soil; Jasper Hill; Mount Camel Range.</p>"]], "producers": ["Jasper Hill", "Wild Duck Creek", "Tellurian", "Heathcote Estate", "Greenstone Vineyards", "Sanguine Estate", "Paul Osicka"], "sources": [["Wine Australia: Register of protected GIs and other terms", "https://www.wineaustralia.com/labelling/register-of-protected-gis-and-other-terms"], ["Wine Australia: Geographical indications", "https://www.wineaustralia.com/labelling/geographical-indications"]], "checked": "2026-11-14"};
APXF["au-henty"] = {"lede": "A huge, sparsely planted region in Victoria's far south-west near Portland and Hamilton, one of the coolest in mainland Australia (about 1,430 growing degree days).", "facts": [["Category", "GI"], ["Recognized", "2000"], ["Vineyard area", "About 139 ha"], ["Main grapes", "Riesling, Chardonnay, Pinot Noir, Cabernet Sauvignon"]], "sections": [["The place", "<p>Crawford River's Rieslings (John Thomson, from 1975) are among the country's best, and Seppelt once sourced Drumborg fruit here for sparkling and Riesling.</p><p>Maritime, windy and cool, on volcanic basalt soils near the coast.</p>"], ["The rules", "<p>Australia's GI system was created in 1993, when amendments to the Australian Wine and Brandy Corporation Act set up the Geographical Indications Committee, partly to meet the terms of the 1994 wine agreement with the European Community, under which Australia also began phasing out names such as Burgundy, Champagne and Port. The committee, now part of Wine Australia, determines boundaries on application from local growers, following criteria that include the area's history, name, geology, climate and the existence of a viticultural identity. A GI on a label requires at least 85% of the wine from that GI, and the same 85% applies to vintage and variety. There are no rules on grapes, yields or winemaking: an Australian GI defines a place, not a style. This is a region, which under the regulations must be a single tract of land with at least five independently owned vineyards of at least five hectares each and usually produce at least 500 tonnes of grapes a year, and must be measurably homogeneous in its grape-growing attributes.</p>"], ["History", "<p>Seppelt planted Drumborg in 1964 for sparkling wine, and John Thomson's Crawford River (1975) made Henty Riesling famous.</p>"], ["In the glass", "<p>Riesling, Pinot Noir, sparkling.</p>"], ["For the exam", "<p>Very cool; Drumborg; Crawford River.</p>"]], "producers": ["Crawford River", "Seppelt (Drumborg)", "Pierrepoint"], "sources": [["Wine Australia: Register of protected GIs and other terms", "https://www.wineaustralia.com/labelling/register-of-protected-gis-and-other-terms"], ["Wine Australia: Geographical indications", "https://www.wineaustralia.com/labelling/geographical-indications"]], "checked": "2026-11-14"};
APXF["au-king-valley"] = {"lede": "A narrow valley rising into the Alps from Milawa, settled after the Second World War by Italian families who grew tobacco.", "facts": [["Category", "GI"], ["Recognized", "2007"], ["Vineyard area", "About 1,483 ha"], ["Main grapes", "Prosecco (Glera), Pinot Grigio, Sangiovese, Nebbiolo, Chardonnay, Riesling"]], "sections": [["The place", "<p>When tobacco collapsed in the 1990s they planted vines, and the Pizzini, Dal Zotto and Brown families made the King Valley Australia's Prosecco capital. Otto Dal Zotto planted the first Prosecco vines in 1999. Since an EU challenge, Australia has defended 'Prosecco' as a grape variety name. Brown Brothers, founded at Milawa in 1889, is the region's oldest producer.</p><p>Vineyards from about 150 m at Milawa to over 800 m at Whitlands; about 1,710 growing degree days, wetter (970 mm) than most.</p>"], ["The rules", "<p>Australia's GI system was created in 1993, when amendments to the Australian Wine and Brandy Corporation Act set up the Geographical Indications Committee, partly to meet the terms of the 1994 wine agreement with the European Community, under which Australia also began phasing out names such as Burgundy, Champagne and Port. The committee, now part of Wine Australia, determines boundaries on application from local growers, following criteria that include the area's history, name, geology, climate and the existence of a viticultural identity. A GI on a label requires at least 85% of the wine from that GI, and the same 85% applies to vintage and variety. There are no rules on grapes, yields or winemaking: an Australian GI defines a place, not a style. This is a region, which under the regulations must be a single tract of land with at least five independently owned vineyards of at least five hectares each and usually produce at least 500 tonnes of grapes a year, and must be measurably homogeneous in its grape-growing attributes.</p>"], ["History", "<p>Italian families who grew tobacco settled the valley after the Second World War; when tobacco collapsed in the 1980s and 1990s, the Pizzinis, Dal Zottos and others planted Italian grapes. Otto Dal Zotto planted Prosecco in 1999, and the valley's success with it led Italy to redefine Prosecco as a place in 2009, starting a long trade dispute over whether Australians can use the name.</p>"], ["In the glass", "<p>Prosecco, Sangiovese, Nebbiolo, Pinot Grigio.</p>"], ["For the exam", "<p>Italian families; tobacco to grapes; Prosecco dispute with Italy.</p>"]], "producers": ["Brown Brothers", "Pizzini", "Dal Zotto", "Chrismont"], "sources": [["Wine Australia: Register of protected GIs and other terms", "https://www.wineaustralia.com/labelling/register-of-protected-gis-and-other-terms"], ["Wine Australia: Geographical indications", "https://www.wineaustralia.com/labelling/geographical-indications"]], "checked": "2026-11-14"};
APXF["au-macedon-ranges"] = {"lede": "The coldest wine region on mainland Australia by Wine Australia's measure (about 1,390 growing degree days), high on the Great Dividing Range north-west of Melbourne around Kyneton, Gisborne, Lancefield and Woodend.", "facts": [["Category", "GI"], ["Recognized", "2002"], ["Vineyard area", "About 215 ha"], ["Main grapes", "Pinot Noir, Chardonnay, Riesling, Shiraz"]], "sections": [["The place", "<p>It is marginal country, where a cold spring can cut a crop in half, but its traditional-method sparkling and taut Pinot and Chardonnay are among Australia's most elegant. Bindi (Michael Dhillon), Curly Flat, Hanging Rock and Granite Hills are the reference producers.</p><p>Altitudes of about 300 to 800 m; granite, sandstone and volcanic soils; windy, with frost risk.</p>"], ["The rules", "<p>Australia's GI system was created in 1993, when amendments to the Australian Wine and Brandy Corporation Act set up the Geographical Indications Committee, partly to meet the terms of the 1994 wine agreement with the European Community, under which Australia also began phasing out names such as Burgundy, Champagne and Port. The committee, now part of Wine Australia, determines boundaries on application from local growers, following criteria that include the area's history, name, geology, climate and the existence of a viticultural identity. A GI on a label requires at least 85% of the wine from that GI, and the same 85% applies to vintage and variety. There are no rules on grapes, yields or winemaking: an Australian GI defines a place, not a style. This is a region, which under the regulations must be a single tract of land with at least five independently owned vineyards of at least five hectares each and usually produce at least 500 tonnes of grapes a year, and must be measurably homogeneous in its grape-growing attributes.</p>"], ["History", "<p>The coldest mainland region by Wine Australia's measure, high on the Great Dividing Range. Bindi and Curly Flat make highly regarded Pinot Noir and Chardonnay.</p>"], ["In the glass", "<p>Taut Pinot Noir, Chardonnay and sparkling.</p>"], ["For the exam", "<p>Coldest mainland region; Bindi; Curly Flat.</p>"]], "producers": ["Bindi", "Curly Flat", "Hanging Rock", "Granite Hills", "Lyons Will"], "sources": [["Wine Australia: Register of protected GIs and other terms", "https://www.wineaustralia.com/labelling/register-of-protected-gis-and-other-terms"], ["Wine Australia: Geographical indications", "https://www.wineaustralia.com/labelling/geographical-indications"]], "checked": "2026-11-14"};
APXF["au-mornington-peninsula"] = {"lede": "A boot-shaped peninsula between Port Phillip Bay and Western Port, an hour south of Melbourne, surrounded by water on three sides.", "facts": [["Category", "GI"], ["Recognized", "1997"], ["Vineyard area", "About 919 ha"], ["Main grapes", "Pinot Noir, Chardonnay, Pinot Gris, Shiraz"]], "sections": [["The place", "<p>Vines arrived in the 1880s, but the modern industry dates from the 1970s, when Baillieu Myer (Elgee Park, 1972) and Nat and Rosalie White (Main Ridge, 1975) planted. Today about 200 small vineyards make Pinot Noir, Chardonnay and Pinot Gris (often labelled Pinot Grigio in a nod to the peninsula's Italian heritage) with a tense, saline freshness. Producers such as Paringa Estate, Kooyong, Stonier, Yabby Lake, Ten Minutes by Tractor, Eldridge and Moorooduc have built an international reputation for Pinot that varies vineyard by vineyard.</p><p>Maritime and cool (about 1,560 growing degree days). Red Hill and Main Ridge, at 150 to 300 m on deep red volcanic soils, are the coolest; Moorooduc and Tuerong, lower and on sandier soils over clay, are warmer and riper. Strong winds at flowering reduce yields.</p>"], ["The rules", "<p>Australia's GI system was created in 1993, when amendments to the Australian Wine and Brandy Corporation Act set up the Geographical Indications Committee, partly to meet the terms of the 1994 wine agreement with the European Community, under which Australia also began phasing out names such as Burgundy, Champagne and Port. The committee, now part of Wine Australia, determines boundaries on application from local growers, following criteria that include the area's history, name, geology, climate and the existence of a viticultural identity. A GI on a label requires at least 85% of the wine from that GI, and the same 85% applies to vintage and variety. There are no rules on grapes, yields or winemaking: an Australian GI defines a place, not a style. This is a region, which under the regulations must be a single tract of land with at least five independently owned vineyards of at least five hectares each and usually produce at least 500 tonnes of grapes a year, and must be measurably homogeneous in its grape-growing attributes.</p>"], ["History", "<p>Vines arrived in the 1880s and disappeared. Baillieu Myer planted Elgee Park in 1972, and the peninsula became one of Australia's leading Pinot Noir and Chardonnay areas, with small estates such as Stonier, Paringa and Ten Minutes by Tractor.</p>"], ["In the glass", "<p>Pinot Noir, Chardonnay, Pinot Gris.</p>"], ["For the exam", "<p>Maritime; Elgee Park 1972; Pinot Noir.</p>"]], "producers": ["Paringa Estate", "Kooyong", "Port Phillip Estate", "Stonier", "Yabby Lake", "Ten Minutes by Tractor", "Main Ridge Estate", "Moorooduc Estate", "Eldridge Estate", "Crittenden Estate", "Quealy"], "sources": [["Wine Australia: Register of protected GIs and other terms", "https://www.wineaustralia.com/labelling/register-of-protected-gis-and-other-terms"], ["Wine Australia: Geographical indications", "https://www.wineaustralia.com/labelling/geographical-indications"]], "checked": "2026-11-14"};
APXF["au-murray-darling"] = {"lede": "One of the three great irrigated regions, straddling the Murray around Mildura, Robinvale and Wentworth in both Victoria and New South Wales, with about 13,500 ha of vines.", "facts": [["Category", "GI"], ["Recognized", "1997"], ["Vineyard area", "About 13,490 ha"], ["Main grapes", "Chardonnay, Shiraz, Cabernet Sauvignon, Sauvignon Blanc, Colombard"]], "sections": [["The place", "<p>In 2026 it crushed about 237,000 tonnes. The Chaffey brothers began irrigation at Mildura in 1887. Lindeman's Karadoc winery made the region's best-known export, Bin 65 Chardonnay, launched in 1985; at its peak several million cases a year were sold.</p><p>About 2,550 growing degree days and 284 mm of rain a year: entirely irrigated. Sandy red mallee soils.</p>"], ["The rules", "<p>Australia's GI system was created in 1993, when amendments to the Australian Wine and Brandy Corporation Act set up the Geographical Indications Committee, partly to meet the terms of the 1994 wine agreement with the European Community, under which Australia also began phasing out names such as Burgundy, Champagne and Port. The committee, now part of Wine Australia, determines boundaries on application from local growers, following criteria that include the area's history, name, geology, climate and the existence of a viticultural identity. A GI on a label requires at least 85% of the wine from that GI, and the same 85% applies to vintage and variety. There are no rules on grapes, yields or winemaking: an Australian GI defines a place, not a style. This is a region, which under the regulations must be a single tract of land with at least five independently owned vineyards of at least five hectares each and usually produce at least 500 tonnes of grapes a year, and must be measurably homogeneous in its grape-growing attributes.</p>"], ["History", "<p>The Chaffey brothers founded the Mildura irrigation colony in 1887. Murray Darling straddles Victoria and New South Wales and grows a large share of Australia's cheap wine.</p>"], ["In the glass", "<p>Inexpensive Chardonnay and reds.</p>"], ["For the exam", "<p>Mildura; Chaffey 1887; cross-border region.</p>"]], "producers": ["Lindeman's", "Trentham Estate", "Deakin Estate"], "sources": [["Wine Australia: Register of protected GIs and other terms", "https://www.wineaustralia.com/labelling/register-of-protected-gis-and-other-terms"], ["Wine Australia: Geographical indications", "https://www.wineaustralia.com/labelling/geographical-indications"]], "checked": "2026-11-14"};
APXF["au-nagambie-lakes"] = {"lede": "A subregion registered in 2001, defined by the lagoons and billabongs of the Goulburn River near Nagambie, the only Australian GI defined by its water bodies.", "facts": [["Category", "GI"], ["Recognized", "2001"], ["Vineyard area", "About 513 ha"], ["Main grapes", "Shiraz, Marsanne, Cabernet Sauvignon, Viognier, Roussanne"]], "sections": [["The place", "<p>It holds Tahbilk, whose 1860 Shiraz block survived phylloxera on sandy soils, and whose Marsanne vineyard (planted from 1927) is one of the largest and oldest in the world. Mitchelton, founded in 1969 with a tower overlooking the river, is the other landmark.</p><p>Wine Australia's description points to the influence of the lakes and the region's red sandy loams with ironstone gravel; the water moderates temperatures at night.</p>"], ["The rules", "<p>Australia's GI system was created in 1993, when amendments to the Australian Wine and Brandy Corporation Act set up the Geographical Indications Committee, partly to meet the terms of the 1994 wine agreement with the European Community, under which Australia also began phasing out names such as Burgundy, Champagne and Port. The committee, now part of Wine Australia, determines boundaries on application from local growers, following criteria that include the area's history, name, geology, climate and the existence of a viticultural identity. A GI on a label requires at least 85% of the wine from that GI, and the same 85% applies to vintage and variety. There are no rules on grapes, yields or winemaking: an Australian GI defines a place, not a style. This is a subregion, which must meet the same tests as a region, at least five vineyards of five hectares and 500 tonnes, and be substantially discrete within its parent region.</p>"], ["History", "<p>Tahbilk, founded in 1860, has Marsanne vines planted in 1927 and Shiraz from 1860, among the oldest in the world. Registered in 2001, Nagambie Lakes is defined by its water, the lagoons and billabongs of the Goulburn, which cool the vineyards; it is often described as the only Australian GI where a body of water shapes the climate this way.</p>"], ["In the glass", "<p>Marsanne that ages to honey; old-vine Shiraz.</p>"], ["For the exam", "<p>GI shaped by its lakes; Tahbilk; 1860 Shiraz; 1927 Marsanne.</p>"]], "producers": ["Tahbilk", "Mitchelton", "Box Grove"], "sources": [["Wine Australia: Register of protected GIs and other terms", "https://www.wineaustralia.com/labelling/register-of-protected-gis-and-other-terms"], ["Wine Australia: Geographical indications", "https://www.wineaustralia.com/labelling/geographical-indications"]], "checked": "2026-11-14"};
APXF["au-north-east-victoria"] = {"lede": "The zone of the Ovens and King valleys, the Victorian Alps and the Murray around Rutherglen: Rutherglen, Glenrowan, Beechworth, King Valley and Alpine Valleys.", "facts": [["Category", "GI"], ["Recognized", "1996"], ["Vineyard area", "About 2,903 ha"], ["Main grapes", "Muscat, Muscadelle, Shiraz, Durif, Prosecco, Sangiovese"]], "sections": [["The place", "<p>The zone is the home of Rutherglen Muscat and Topaque and of the Italian families of the King Valley, and it climbs from the Murray plains to alpine vineyards at almost 1,000 m.</p>"], ["The rules", "<p>Australia's GI system was created in 1993, when amendments to the Australian Wine and Brandy Corporation Act set up the Geographical Indications Committee, partly to meet the terms of the 1994 wine agreement with the European Community, under which Australia also began phasing out names such as Burgundy, Champagne and Port. The committee, now part of Wine Australia, determines boundaries on application from local growers, following criteria that include the area's history, name, geology, climate and the existence of a viticultural identity. A GI on a label requires at least 85% of the wine from that GI, and the same 85% applies to vintage and variety. There are no rules on grapes, yields or winemaking: an Australian GI defines a place, not a style. This is a zone, a large administrative division within a state; zones were drawn to cover the wine states completely, and most regions sit inside one.</p>"], ["History", "<p>The North East Victoria zone covers the Murray at Rutherglen and the Alpine valleys.</p>"], ["In the glass", "<p>Fortified Muscat and Topaque; Italian varieties.</p>"], ["For the exam", "<p>Zone: Rutherglen, Glenrowan, Beechworth, King Valley, Alpine Valleys.</p>"]], "producers": ["Brown Brothers", "Chambers Rosewood", "Giaconda"], "sources": [["Wine Australia: Register of protected GIs and other terms", "https://www.wineaustralia.com/labelling/register-of-protected-gis-and-other-terms"], ["Wine Australia: Geographical indications", "https://www.wineaustralia.com/labelling/geographical-indications"]], "checked": "2026-11-14"};
APXF["au-north-west-victoria"] = {"lede": "The Victorian bank of the Murray, from Swan Hill to Mildura.", "facts": [["Category", "GI"], ["Recognized", "1996"], ["Vineyard area", "About 8,656 ha"], ["Main grapes", "Chardonnay, Shiraz, Cabernet Sauvignon, Sauvignon Blanc"]], "sections": [["The place", "<p>Its regions, Murray Darling and Swan Hill, cross the river into New South Wales. Almost all of its fruit is irrigated from the Murray and goes into branded and bulk wine, much of it labelled South Eastern Australia.</p><p>Hot and irrigated.</p>"], ["The rules", "<p>Australia's GI system was created in 1993, when amendments to the Australian Wine and Brandy Corporation Act set up the Geographical Indications Committee, partly to meet the terms of the 1994 wine agreement with the European Community, under which Australia also began phasing out names such as Burgundy, Champagne and Port. The committee, now part of Wine Australia, determines boundaries on application from local growers, following criteria that include the area's history, name, geology, climate and the existence of a viticultural identity. A GI on a label requires at least 85% of the wine from that GI, and the same 85% applies to vintage and variety. There are no rules on grapes, yields or winemaking: an Australian GI defines a place, not a style. This is a zone, a large administrative division within a state; zones were drawn to cover the wine states completely, and most regions sit inside one.</p>"], ["History", "<p>The North West Victoria zone covers the irrigated Murray around Mildura, settled by the Chaffey brothers' irrigation colony in 1887.</p>"], ["In the glass", "<p>Bulk wine.</p>"], ["For the exam", "<p>Zone: Murray Darling, Swan Hill.</p>"]], "producers": ["Lindeman's (Karadoc)"], "sources": [["Wine Australia: Register of protected GIs and other terms", "https://www.wineaustralia.com/labelling/register-of-protected-gis-and-other-terms"], ["Wine Australia: Geographical indications", "https://www.wineaustralia.com/labelling/geographical-indications"]], "checked": "2026-11-14"};
APXF["au-port-phillip"] = {"lede": "The zone around Melbourne and Port Phillip Bay, containing the Yarra Valley, Mornington Peninsula, Geelong, Macedon Ranges and Sunbury.", "facts": [["Category", "GI"], ["Recognized", "1996"], ["Vineyard area", "About 4,329 ha"], ["Main grapes", "Pinot Noir, Chardonnay, Shiraz, Cabernet Sauvignon"]], "sections": [["The place", "<p>It is Victoria's cool-climate core and the centre of Australian Pinot Noir and Chardonnay.</p><p>Bay and Bass Strait moderate the coastal regions; the Great Dividing Range lifts Macedon.</p>"], ["The rules", "<p>Australia's GI system was created in 1993, when amendments to the Australian Wine and Brandy Corporation Act set up the Geographical Indications Committee, partly to meet the terms of the 1994 wine agreement with the European Community, under which Australia also began phasing out names such as Burgundy, Champagne and Port. The committee, now part of Wine Australia, determines boundaries on application from local growers, following criteria that include the area's history, name, geology, climate and the existence of a viticultural identity. A GI on a label requires at least 85% of the wine from that GI, and the same 85% applies to vintage and variety. There are no rules on grapes, yields or winemaking: an Australian GI defines a place, not a style. This is a zone, a large administrative division within a state; zones were drawn to cover the wine states completely, and most regions sit inside one.</p>"], ["History", "<p>The Port Phillip zone around Melbourne holds the regions closest to the city, the heart of Victoria's nineteenth-century wine industry and of its modern cool-climate revival.</p>"], ["In the glass", "<p>Pinot Noir, Chardonnay, Shiraz.</p>"], ["For the exam", "<p>Zone: Yarra Valley, Mornington Peninsula, Geelong, Macedon Ranges, Sunbury.</p>"]], "producers": ["Yarra Yering", "Mount Mary", "Bannockburn"], "sources": [["Wine Australia: Register of protected GIs and other terms", "https://www.wineaustralia.com/labelling/register-of-protected-gis-and-other-terms"], ["Wine Australia: Geographical indications", "https://www.wineaustralia.com/labelling/geographical-indications"]], "checked": "2026-11-14"};
APXF["au-pyrenees"] = {"lede": "Rolling hills around Avoca and Moonambel, named after the Pyrenees by the explorer Thomas Mitchell.", "facts": [["Category", "GI"], ["Recognized", "2000"], ["Vineyard area", "About 869 ha"], ["Main grapes", "Shiraz, Cabernet Sauvignon, Sauvignon Blanc, Chardonnay"]], "sections": [["The place", "<p>Rémy Martin planted Chateau Remy (now Blue Pyrenees) for brandy and sparkling in 1963, and Taltarni and Dalwhinnie built the reputation for firm, minty Shiraz and Cabernet.</p><p>About 1,710 growing degree days; 507 mm of rain; quartz-gravel and clay loams at 200 to 800 m.</p>"], ["The rules", "<p>Australia's GI system was created in 1993, when amendments to the Australian Wine and Brandy Corporation Act set up the Geographical Indications Committee, partly to meet the terms of the 1994 wine agreement with the European Community, under which Australia also began phasing out names such as Burgundy, Champagne and Port. The committee, now part of Wine Australia, determines boundaries on application from local growers, following criteria that include the area's history, name, geology, climate and the existence of a viticultural identity. A GI on a label requires at least 85% of the wine from that GI, and the same 85% applies to vintage and variety. There are no rules on grapes, yields or winemaking: an Australian GI defines a place, not a style. This is a region, which under the regulations must be a single tract of land with at least five independently owned vineyards of at least five hectares each and usually produce at least 500 tonnes of grapes a year, and must be measurably homogeneous in its grape-growing attributes.</p>"], ["History", "<p>Explorer Thomas Mitchell named the ranges after the Pyrenees in 1836. Rémy Martin planted Chateau Remy in 1963 for brandy and sparkling wine; it is now Blue Pyrenees.</p>"], ["In the glass", "<p>Shiraz, Cabernet.</p>"], ["For the exam", "<p>Named by Mitchell; Rémy Martin 1963.</p>"]], "producers": ["Dalwhinnie", "Taltarni", "Blue Pyrenees", "Summerfield", "Mount Avoca"], "sources": [["Wine Australia: Register of protected GIs and other terms", "https://www.wineaustralia.com/labelling/register-of-protected-gis-and-other-terms"], ["Wine Australia: Geographical indications", "https://www.wineaustralia.com/labelling/geographical-indications"]], "checked": "2026-11-14"};
APXF["au-rutherglen"] = {"lede": "Rutherglen, on the Murray River in north-east Victoria, makes one of the world's great fortified wines, and it does so from grapes ripened to raisins on the vine.", "facts": [["Category", "GI"], ["Recognized", "1997"], ["Vineyard area", "About 778 ha"], ["Main grapes", "Muscat à Petits Grains Rouge ('Rutherglen Brown Muscat'), Muscadelle, Durif, Shiraz"]], "sections": [["The place", "<p>Gold was found here in 1860; the gold ran out within a decade, but many miners stayed and planted vines, and by the 1880s the region was exporting to London. Phylloxera arrived in 1899 and the region shrank, but a handful of families (Chambers, Morris, Campbell, Sutherland Smith at All Saints, Stanton & Killeen) kept their soleras of fortified wine going, some for more than 140 years.</p><p>Rutherglen Muscat is made from a dark-skinned clone of Muscat à Petits Grains, left on the vine until the berries shrivel and reach 17 to 20 degrees Baumé. Fermentation is stopped early with grape spirit, and the wine then ages for years in old casks stacked in hot iron sheds, where heat concentrates it and the 'angels' share' takes about half the volume over 20 years. The result is dark brown, viscous and tastes of raisin, toffee, coffee and rose petal. Topaque, made the same way from Muscadelle, was called Tokay until EU agreements retired the name in 2010; it tastes of malt, tea leaf and butterscotch.</p><p>The producers' Muscat of Rutherglen network classifies these wines on four tiers by richness and age: Rutherglen (an average age of about 3 to 5 years), Classic (6 to 10), Grand (11 to 19) and Rare (more than 20 years). Only a few hundred bottles of the Rare wines are released each year; Chambers Rosewood and Morris have barrels from the 1890s and earlier in their blends. The region also makes dense, inky Durif, a red grape that found its best Australian home here.</p><p>Warm and continental (about 2,080 growing degree days), with hot days, cool nights and a long dry autumn that lets fruit shrivel safely on the vine. Soils are red loams and alluvial sands along the Murray; vineyards sit at about 120 to 590 m.</p>"], ["The rules", "<p>Australia's GI system was created in 1993, when amendments to the Australian Wine and Brandy Corporation Act set up the Geographical Indications Committee, partly to meet the terms of the 1994 wine agreement with the European Community, under which Australia also began phasing out names such as Burgundy, Champagne and Port. The committee, now part of Wine Australia, determines boundaries on application from local growers, following criteria that include the area's history, name, geology, climate and the existence of a viticultural identity. A GI on a label requires at least 85% of the wine from that GI, and the same 85% applies to vintage and variety. There are no rules on grapes, yields or winemaking: an Australian GI defines a place, not a style. This is a region, which under the regulations must be a single tract of land with at least five independently owned vineyards of at least five hectares each and usually produce at least 500 tonnes of grapes a year, and must be measurably homogeneous in its grape-growing attributes.</p>"], ["History", "<p>Rutherglen's fortified wines come from Muscat à Petits Grains Rouge and Muscadelle ripened to raisins, then aged in old casks under the iron roofs of the wineries. Families such as Chambers, Campbells, Morris, Stanton & Killeen and Pfeiffer have made them since the late nineteenth century. In 1995 producers agreed a classification: Rutherglen, Classic, Grand and Rare, by age and richness. Under the 2008 agreement with the EU, the name Tokay was dropped for Muscadelle wines, which became Topaque.</p>"], ["In the glass", "<p>Fortified Muscat with raisin, toffee and rose; Topaque with tea leaf, butterscotch and malt; Durif reds.</p>"], ["For the exam", "<p>Muscat and Topaque; classification Rutherglen, Classic, Grand, Rare; Tokay renamed Topaque.</p>"]], "producers": ["Chambers Rosewood", "Morris", "Campbells", "All Saints Estate", "Stanton & Killeen", "Pfeiffer", "Buller", "Cofield"], "sources": [["Wine Australia: Register of protected GIs and other terms", "https://www.wineaustralia.com/labelling/register-of-protected-gis-and-other-terms"], ["Wine Australia: Geographical indications", "https://www.wineaustralia.com/labelling/geographical-indications"]], "checked": "2026-11-14"};
APXF["au-strathbogie-ranges"] = {"lede": "A granite plateau between the Goulburn Valley and the Upper Goulburn at roughly 150 to 1,000 m, registered in 2002, supplying cool-climate Riesling, Chardonnay and sparkling base as well as some fine Shiraz.", "facts": [["Category", "GI"], ["Recognized", "2002"], ["Vineyard area", "About 533 ha"], ["Main grapes", "Riesling, Chardonnay, Shiraz, Pinot Noir"]], "sections": [["The place", "<p>Granite-derived sandy soils; about 1,620 growing degree days.</p>"], ["The rules", "<p>Australia's GI system was created in 1993, when amendments to the Australian Wine and Brandy Corporation Act set up the Geographical Indications Committee, partly to meet the terms of the 1994 wine agreement with the European Community, under which Australia also began phasing out names such as Burgundy, Champagne and Port. The committee, now part of Wine Australia, determines boundaries on application from local growers, following criteria that include the area's history, name, geology, climate and the existence of a viticultural identity. A GI on a label requires at least 85% of the wine from that GI, and the same 85% applies to vintage and variety. There are no rules on grapes, yields or winemaking: an Australian GI defines a place, not a style. This is a region, which under the regulations must be a single tract of land with at least five independently owned vineyards of at least five hectares each and usually produce at least 500 tonnes of grapes a year, and must be measurably homogeneous in its grape-growing attributes.</p>"], ["History", "<p>Registered in 2002 on a granite plateau.</p>"], ["In the glass", "<p>Riesling, Chardonnay, sparkling.</p>"], ["For the exam", "<p>Granite plateau.</p>"]], "producers": ["Fowles Wine", "Maygars Hill", "Elgo Estate"], "sources": [["Wine Australia: Register of protected GIs and other terms", "https://www.wineaustralia.com/labelling/register-of-protected-gis-and-other-terms"], ["Wine Australia: Geographical indications", "https://www.wineaustralia.com/labelling/geographical-indications"]], "checked": "2026-11-14"};
APXF["au-sunbury"] = {"lede": "A small region just north-west of Melbourne airport, with a nineteenth-century heritage: Craiglee's bluestone winery was built in 1864, and its 1872 Hermitage was still being opened in the twentieth century.", "facts": [["Category", "GI"], ["Recognized", "1998"], ["Vineyard area", "About 100 ha"], ["Main grapes", "Shiraz, Chardonnay, Cabernet Sauvignon"]], "sections": [["The place", "<p>Today Craiglee and Galli Estate make peppery Shiraz and Chardonnay.</p><p>Dry (about 530 mm), windy plains with volcanic soils.</p>"], ["The rules", "<p>Australia's GI system was created in 1993, when amendments to the Australian Wine and Brandy Corporation Act set up the Geographical Indications Committee, partly to meet the terms of the 1994 wine agreement with the European Community, under which Australia also began phasing out names such as Burgundy, Champagne and Port. The committee, now part of Wine Australia, determines boundaries on application from local growers, following criteria that include the area's history, name, geology, climate and the existence of a viticultural identity. A GI on a label requires at least 85% of the wine from that GI, and the same 85% applies to vintage and variety. There are no rules on grapes, yields or winemaking: an Australian GI defines a place, not a style. This is a region, which under the regulations must be a single tract of land with at least five independently owned vineyards of at least five hectares each and usually produce at least 500 tonnes of grapes a year, and must be measurably homogeneous in its grape-growing attributes.</p>"], ["History", "<p>Craiglee's bluestone winery was built in 1864; bottles of its 1872 Hermitage survived to be tasted a century later. Pat Carmody revived it in 1976.</p>"], ["In the glass", "<p>Peppery Shiraz.</p>"], ["For the exam", "<p>Craiglee 1864; near Melbourne airport.</p>"]], "producers": ["Craiglee", "Galli Estate"], "sources": [["Wine Australia: Register of protected GIs and other terms", "https://www.wineaustralia.com/labelling/register-of-protected-gis-and-other-terms"], ["Wine Australia: Geographical indications", "https://www.wineaustralia.com/labelling/geographical-indications"]], "checked": "2026-11-14"};
APXF["au-swan-hill"] = {"lede": "An irrigated Murray River region around Swan Hill and Robinvale, straddling Victoria and New South Wales, producing about 35,000 to 47,000 tonnes a year for branded and bulk wine.", "facts": [["Category", "GI"], ["Recognized", "1996"], ["Vineyard area", "About 2,086 ha"], ["Main grapes", "Chardonnay, Shiraz, Colombard"]], "sections": [["The place", "<p>Like the Murray Darling region downstream, it depends entirely on river water allocations, which in drought years can decide the size of the crop.</p><p>Hot (about 2,360 growing degree days), very dry (329 mm), irrigated.</p>"], ["The rules", "<p>Australia's GI system was created in 1993, when amendments to the Australian Wine and Brandy Corporation Act set up the Geographical Indications Committee, partly to meet the terms of the 1994 wine agreement with the European Community, under which Australia also began phasing out names such as Burgundy, Champagne and Port. The committee, now part of Wine Australia, determines boundaries on application from local growers, following criteria that include the area's history, name, geology, climate and the existence of a viticultural identity. A GI on a label requires at least 85% of the wine from that GI, and the same 85% applies to vintage and variety. There are no rules on grapes, yields or winemaking: an Australian GI defines a place, not a style. This is a region, which under the regulations must be a single tract of land with at least five independently owned vineyards of at least five hectares each and usually produce at least 500 tonnes of grapes a year, and must be measurably homogeneous in its grape-growing attributes.</p>"], ["History", "<p>An irrigated Murray River region straddling Victoria and New South Wales.</p>"], ["In the glass", "<p>Bulk wine.</p>"], ["For the exam", "<p>Cross-border irrigated region.</p>"]], "producers": ["Andrew Peace Wines"], "sources": [["Wine Australia: Register of protected GIs and other terms", "https://www.wineaustralia.com/labelling/register-of-protected-gis-and-other-terms"], ["Wine Australia: Geographical indications", "https://www.wineaustralia.com/labelling/geographical-indications"]], "checked": "2026-11-14"};
APXF["au-upper-goulburn"] = {"lede": "Hilly country around Mansfield, Alexandra and Lake Eildon at the foot of the Victorian Alps, registered in 2003.", "facts": [["Category", "GI"], ["Recognized", "2003"], ["Vineyard area", "About 288 ha"], ["Main grapes", "Chardonnay, Pinot Noir, Riesling, Sauvignon Blanc"]], "sections": [["The place", "<p>Delatite, founded by the Ritchie family in 1968, is its best-known estate, with aromatic whites and biodynamic farming.</p><p>Elevations up to about 1,000 m, cool (about 1,540 growing degree days).</p>"], ["The rules", "<p>Australia's GI system was created in 1993, when amendments to the Australian Wine and Brandy Corporation Act set up the Geographical Indications Committee, partly to meet the terms of the 1994 wine agreement with the European Community, under which Australia also began phasing out names such as Burgundy, Champagne and Port. The committee, now part of Wine Australia, determines boundaries on application from local growers, following criteria that include the area's history, name, geology, climate and the existence of a viticultural identity. A GI on a label requires at least 85% of the wine from that GI, and the same 85% applies to vintage and variety. There are no rules on grapes, yields or winemaking: an Australian GI defines a place, not a style. This is a region, which under the regulations must be a single tract of land with at least five independently owned vineyards of at least five hectares each and usually produce at least 500 tonnes of grapes a year, and must be measurably homogeneous in its grape-growing attributes.</p>"], ["History", "<p>Delatite, founded by the Ritchie family in 1968, pioneered vines near Mansfield; registered 2003.</p>"], ["In the glass", "<p>Riesling, Gewürztraminer, Pinot Noir.</p>"], ["For the exam", "<p>Delatite.</p>"]], "producers": ["Delatite", "Mount Cathedral"], "sources": [["Wine Australia: Register of protected GIs and other terms", "https://www.wineaustralia.com/labelling/register-of-protected-gis-and-other-terms"], ["Wine Australia: Geographical indications", "https://www.wineaustralia.com/labelling/geographical-indications"]], "checked": "2026-11-14"};
APXF["au-victoria"] = {"lede": "The state GI for Victoria, used for blends across its 21 regions.", "facts": [["Category", "GI"], ["Recognized", ""], ["Main grapes", "Shiraz, Chardonnay, Pinot Noir, Cabernet Sauvignon, Sauvignon Blanc, Muscat"]], "sections": [["The place", "<p>Victoria has more registered regions than any other state, reflecting a climate range from the hot Murray to the cold Macedon Ranges, and the family-scale, region-driven industry that rebuilt itself after phylloxera.</p><p>Cool maritime south, alpine centre and north-east, hot irrigated north-west.</p>"], ["The rules", "<p>Australia's GI system was created in 1993, when amendments to the Australian Wine and Brandy Corporation Act set up the Geographical Indications Committee, partly to meet the terms of the 1994 wine agreement with the European Community, under which Australia also began phasing out names such as Burgundy, Champagne and Port. The committee, now part of Wine Australia, determines boundaries on application from local growers, following criteria that include the area's history, name, geology, climate and the existence of a viticultural identity. A GI on a label requires at least 85% of the wine from that GI, and the same 85% applies to vintage and variety. There are no rules on grapes, yields or winemaking: an Australian GI defines a place, not a style. This is a state or territory GI, the top level of the hierarchy (state, zone, region, subregion).</p>"], ["History", "<p>In the 1880s Victoria was Australia's leading wine colony, with vineyards from the Yarra to the goldfields. Phylloxera, found at Geelong in 1877, spread north and destroyed much of the industry, and many regions disappeared until the 1960s and 1970s revival. Victoria now has more GI regions than any other state.</p>"], ["In the glass", "<p>Blends across Victoria's 21 regions.</p>"], ["For the exam", "<p>Leading colony in the 1880s; phylloxera from 1877; most regions of any state.</p>"]], "producers": ["Brown Brothers", "Tahbilk", "De Bortoli"], "sources": [["Wine Australia: Register of protected GIs and other terms", "https://www.wineaustralia.com/labelling/register-of-protected-gis-and-other-terms"], ["Wine Australia: Geographical indications", "https://www.wineaustralia.com/labelling/geographical-indications"]], "checked": "2026-11-14"};
APXF["au-western-victoria"] = {"lede": "The zone of western Victoria's ranges and plains: Grampians (with Great Western), Pyrenees and Henty.", "facts": [["Category", "GI"], ["Recognized", "1996"], ["Vineyard area", "About 1,714 ha"], ["Main grapes", "Shiraz, Riesling, Cabernet Sauvignon, Chardonnay"]], "sections": [["The place", "<p>It is one of the coolest parts of the state, and its historic centre is the gold-rush town of Great Western, where wine has been made at Best's and at the cellars that became Seppelt since the 1860s.</p>"], ["The rules", "<p>Australia's GI system was created in 1993, when amendments to the Australian Wine and Brandy Corporation Act set up the Geographical Indications Committee, partly to meet the terms of the 1994 wine agreement with the European Community, under which Australia also began phasing out names such as Burgundy, Champagne and Port. The committee, now part of Wine Australia, determines boundaries on application from local growers, following criteria that include the area's history, name, geology, climate and the existence of a viticultural identity. A GI on a label requires at least 85% of the wine from that GI, and the same 85% applies to vintage and variety. There are no rules on grapes, yields or winemaking: an Australian GI defines a place, not a style. This is a zone, a large administrative division within a state; zones were drawn to cover the wine states completely, and most regions sit inside one.</p>"], ["History", "<p>The Western Victoria zone covers the Grampians, Pyrenees and Henty, cool regions famous for peppery Shiraz.</p>"], ["In the glass", "<p>Shiraz, Riesling, sparkling.</p>"], ["For the exam", "<p>Zone: Grampians, Pyrenees, Henty.</p>"]], "producers": ["Best's", "Seppelt"], "sources": [["Wine Australia: Register of protected GIs and other terms", "https://www.wineaustralia.com/labelling/register-of-protected-gis-and-other-terms"], ["Wine Australia: Geographical indications", "https://www.wineaustralia.com/labelling/geographical-indications"]], "checked": "2026-11-14"};
APXF["au-yarra-valley"] = {"lede": "The Yarra Valley, an hour east of Melbourne, was Victoria's first wine region and is its most celebrated.", "facts": [["Category", "GI"], ["Recognized", "1996"], ["Vineyard area", "About 2,535 ha"], ["Main grapes", "Pinot Noir, Chardonnay, Cabernet Sauvignon, Shiraz, Sauvignon Blanc, Nebbiolo"]], "sections": [["The place", "<p>Swiss settlers planted it from the 1840s: Paul de Castella at Yering Station, his brother Hubert at St Hubert's and Guillaume de Pury at Yeringberg. In 1889 a Yering wine won a grand prix at the Paris Exposition. Then fashion, phylloxera fears and the dairy industry wiped it out; the last vintage at Yeringberg in its first life was 1921.</p><p>Doctors and scientists brought it back. Dr Reg Egan replanted Wantirna Estate in 1963, Dr Bailey Carrodus founded Yarra Yering in 1969 and Dr John Middleton Mount Mary in 1971, both making Bordeaux and Burgundy styles of rare finesse. Moët & Chandon chose the valley for Domaine Chandon in 1986, and since the 2000s producers such as Giant Steps, Oakridge, Mac Forbes, Yarra Yering under Sarah Crowe, and Timo Mayer have made it Australia's best-known source of elegant Pinot Noir and tight, struck-match Chardonnay, as well as perfumed, medium-bodied Shiraz and Cabernet.</p><p>The region is split by geology and altitude. The lower, warmer valley floor and northern slopes (Coldstream, Dixons Creek, Gruyere) suit Cabernet and Shiraz on grey sandy clay loams; the Upper Yarra (Hoddles Creek, Seville, Woori Yallock), on deep red volcanic soils at up to about 400 m, is cooler and wetter and makes taut Chardonnay and Pinot. Wine Australia records about 1,440 growing degree days, among the coolest of mainland Australia's major regions.</p><p>Rainfall around 1,080 mm a year and 550 mm in the growing season, high for Australia. Grey sandy loams over clay and sandstone on the valley floor and northern hillsides; red volcanic krasnozem in the Upper Yarra. Bushfires (2009) and smoke taint (2020) are recurring risks.</p>"], ["The rules", "<p>Australia's GI system was created in 1993, when amendments to the Australian Wine and Brandy Corporation Act set up the Geographical Indications Committee, partly to meet the terms of the 1994 wine agreement with the European Community, under which Australia also began phasing out names such as Burgundy, Champagne and Port. The committee, now part of Wine Australia, determines boundaries on application from local growers, following criteria that include the area's history, name, geology, climate and the existence of a viticultural identity. A GI on a label requires at least 85% of the wine from that GI, and the same 85% applies to vintage and variety. There are no rules on grapes, yields or winemaking: an Australian GI defines a place, not a style. This is a region, which under the regulations must be a single tract of land with at least five independently owned vineyards of at least five hectares each and usually produce at least 500 tonnes of grapes a year, and must be measurably homogeneous in its grape-growing attributes.</p>"], ["History", "<p>William Ryrie planted the first vines in 1838. Swiss settlers, including Paul de Castella at Yering and Hubert de Castella at St Hubert's, built a celebrated industry; Yarra wines won top awards at international exhibitions in the 1880s. Changing tastes toward fortified wine and the Depression ended it by the 1920s. Doctors revived it in the late 1960s and 1970s: Bailey Carrodus at Yarra Yering (1969), John Middleton at Mount Mary (1971) and Peter McMahon at Seville Estate. Moët & Chandon chose the valley for Domaine Chandon in 1986. The 2009 Black Saturday fires burned vineyards and smoke-tainted a vintage. Registered 1996.</p>"], ["In the glass", "<p>Elegant Pinot Noir, fine Chardonnay, medium-bodied Cabernet and Shiraz; sparkling wine.</p>"], ["For the exam", "<p>Ryrie 1838; Swiss de Castellas; Yarra Yering, Mount Mary; Domaine Chandon 1986.</p>"]], "producers": ["Mount Mary", "Yarra Yering", "Yeringberg", "De Bortoli", "Giant Steps", "Oakridge", "Coldstream Hills", "Domaine Chandon", "Hoddles Creek Estate", "Mac Forbes", "Timo Mayer", "Seville Estate", "Toolangi", "Punch", "Luke Lambert"], "sources": [["Wine Australia: Register of protected GIs and other terms", "https://www.wineaustralia.com/labelling/register-of-protected-gis-and-other-terms"], ["Wine Australia: Geographical indications", "https://www.wineaustralia.com/labelling/geographical-indications"]], "checked": "2026-11-14"};
})();
